1	package api
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"io"
7		"math"
8		"net/http"
9		"regexp"
10		"strconv"
11		"strings"
12		"time"
13	
14		"github.com/gin-gonic/gin"
15	)
16	
17	// Parameter names accepted on every entry point. The first name of each list
18	// is the canonical name used in responses.
19	var (
20		serviceNameKeys = []string{"service_name", "serviceName", "service"}
21		instanceIDKeys  = []string{"instance_id", "instanceId", "instance", "id"}
22		addressKeys     = []string{"address", "addr", "host", "endpoint"}
23		portKeys        = []string{"port"}
24		healthKeys      = []string{"health", "healthy", "status", "state"}
25		weightKeys      = []string{"weight"}
26		heartbeatKeys   = []string{"heartbeat_at", "heartbeatAt", "heartbeat", "heartbeat_time", "heartbeatTime", "last_heartbeat"}
27		evaluateAtKeys  = []string{"evaluate_at", "evaluateAt", "at", "now", "evaluate_time", "evaluateTime"}
28		timeoutKeys     = []string{"heartbeat_timeout", "heartbeatTimeout", "timeout", "timeout_seconds", "timeoutSeconds", "heartbeat_timeout_seconds"}
29	)
30	
31	type apiError struct {
32		status  int
33		code    string
34		message string
35	}
36	
37	func errInvalidParameter(message string) *apiError {
38		return &apiError{http.StatusBadRequest, "invalid_parameter", message}
39	}
40	
41	func errInstanceNotFound() *apiError {
42		return &apiError{http.StatusNotFound, "instance_not_found", "service instance not found"}
43	}
44	
45	func errStorageUnavailable() *apiError {
46		return &apiError{http.StatusServiceUnavailable, "storage_unavailable", "database is not available"}
47	}
48	
49	func writeError(c *gin.Context, e *apiError) {
50		c.JSON(e.status, gin.H{"error": gin.H{"code": e.code, "message": e.message}})
51	}
52	
53	// paramBag merges JSON body fields and query parameters, keeping route path
54	// parameters separate. Body fields win over query parameters; path
55	// parameters are read through locateText and win over both of them.
56	type paramBag struct {
57		values map[string]any
58		path   map[string]any
59	}
60	
61	func buildParamBag(c *gin.Context) (*paramBag, *apiError) {
62		bag := &paramBag{
63			values: make(map[string]any),
64			path:   make(map[string]any),
65		}
66	
67		for key, values := range c.Request.URL.Query() {
68			if len(values) > 0 {
69				bag.values[key] = values[0]
70			}
71		}
72	
73		// A non-empty body must be exactly one JSON object surrounded only by
74		// JSON whitespace: a null, array or other bare value, a truncated object,
75		// a second JSON value or a stray closing bracket are all parameter
76		// errors, even when the query parameters alone would complete the
77		// request. An empty or whitespace-only body carries no fields, so the
78		// query-parameter lookup rules still apply; an empty {} object merges
79		// with query parameters like any other (empty) field set.
80		if c.Request.Body != nil {
81			body, present, apiErr := readOptionalObjectBody(c)
82			if apiErr != nil {
83				return nil, apiErr
84			}
85			if present {
86				for key, value := range body {
87					bag.values[key] = value
88				}
89			}
90		}
91	
92		for _, param := range c.Params {
93			bag.path[param.Key] = param.Value
94		}
95		return bag, nil
96	}
97	
98	// decodeSingleJSONObject decodes raw as exactly one complete JSON object
99	// surrounded only by JSON whitespace. It returns present=false for an empty
100	// or whitespace-only payload. A JSON null, array or other bare value, a
101	// truncated object, a second JSON value, or a stray closing bracket after
102	// the object (immediately or across whitespace) are all parameter errors.
103	//
104	// Decoder.More cannot be used to check completeness: it reports false for a
105	// dangling "}" or "]" because those are not value tokens. A second Decode
106	// must therefore return exactly io.EOF, which is true only once the object
107	// has ended and nothing but whitespace remains.
108	func decodeSingleJSONObject(raw []byte) (body map[string]any, present bool, apiErr *apiError) {
109		if len(bytes.TrimSpace(raw)) == 0 {
110			return nil, false, nil
111		}
112		decoder := json.NewDecoder(bytes.NewReader(raw))
113		// UseNumber keeps every JSON number as its literal text so integer
114		// fields (port) can be parsed exactly, without the float64 rounding
115		// that json.Unmarshal would apply.
116		decoder.UseNumber()
117		var decoded map[string]any
118		if err := decoder.Decode(&decoded); err != nil || decoded == nil {
119			return nil, false, errInvalidParameter("request body must be a JSON object")
120		}
121		var trailing json.RawMessage
122		if err := decoder.Decode(&trailing); err != io.EOF {
123			return nil, false, errInvalidParameter("request body must be a single JSON object")
124		}
125		return decoded, true, nil
126	}
127	
128	// readOptionalObjectBody reads a body that may be absent: no body or only
129	// JSON whitespace yields present=false so the entry falls back to its query
130	// parameter rules, while every non-empty non-object payload is a parameter
131	// error.
132	func readOptionalObjectBody(c *gin.Context) (map[string]any, bool, *apiError) {
133		if c.Request.Body == nil {
134			return nil, false, nil
135		}
136		raw, err := io.ReadAll(c.Request.Body)
137		if err != nil {
138			return nil, false, errInvalidParameter("request body cannot be read")
139		}
140		return decodeSingleJSONObject(raw)
141	}
142	
143	// readStrictObjectBody requires the body to be exactly one JSON object
144	// surrounded only by JSON whitespace. It is used by the batch entries whose
145	// contract forbids query-parameter merging: a missing/empty body, a JSON
146	// null, array or other bare value, a second JSON value, or a stray closing
147	// bracket after the object are all parameter errors, even when the first
148	// object carries complete, valid entries.
149	func readStrictObjectBody(c *gin.Context) (map[string]any, *apiError) {
150		if c.Request.Body == nil {
151			return nil, errInvalidParameter("request body must be a JSON object")
152		}
153		raw, err := io.ReadAll(c.Request.Body)
154		if err != nil {
155			return nil, errInvalidParameter("request body cannot be read")
156		}
157		body, present, apiErr := decodeSingleJSONObject(raw)
158		if apiErr != nil {
159			return nil, apiErr
160		}
161		if !present {
162			return nil, errInvalidParameter("request body must be a JSON object")
163		}
164		return body, nil
165	}
166	
167	// buildStrictObjectBag is a paramBag populated from exactly one JSON object:
168	// unlike buildParamBag it never reads query parameters, so a rejected or
169	// missing body field cannot be repaired through the URL. Path parameters are
170	// still recorded so path locators keep winning.
171	func buildStrictObjectBag(c *gin.Context) (*paramBag, *apiError) {
172		body, apiErr := readStrictObjectBody(c)
173		if apiErr != nil {
174			return nil, apiErr
175		}
176		bag := &paramBag{
177			values: make(map[string]any, len(body)),
178			path:   make(map[string]any),
179		}
180		for key, value := range body {
181			bag.values[key] = value
182		}
183		for _, param := range c.Params {
184			bag.path[param.Key] = param.Value
185		}
186		return bag, nil
187	}
188	
189	func (b *paramBag) get(keys []string) (any, bool) {
190		for _, key := range keys {
191			if value, ok := b.values[key]; ok {
192				return value, true
193			}
194		}
195		return nil, false
196	}
197	
198	// locateText resolves one locator field (service name or instance id). A
199	// value carried by the route path always wins: a conflicting, empty or
200	// non-string value of the same field in the body or query string is ignored,
201	// and a blank path segment is a parameter error that cannot be filled from
202	// another source. Only when the route carries no such segment does the field
203	// fall back to the existing body/query lookup rules.
204	func (b *paramBag) locateText(pathKey string, keys []string, message string) (string, *apiError) {
205		if raw, fromPath := b.path[pathKey]; fromPath {
206			text := strings.TrimSpace(stringValue(raw))
207			if text == "" {
208				return "", errInvalidParameter(message)
209			}
210			return text, nil
211		}
212		return b.requiredText(keys, message)
213	}
214	
215	// readJSONObject requires the request body to be a single JSON object. An
216	// empty body, a JSON array or any non-object payload is a parameter error.
217	// It is used by the batch entry points whose contract forbids merging query
218	// parameters or accepting a bare value.
219	func readJSONObject(c *gin.Context) (map[string]any, *apiError) {
220		if c.Request.Body == nil {
221			return nil, errInvalidParameter("request body must be a JSON object")
222		}
223		raw, err := io.ReadAll(c.Request.Body)
224		if err != nil {
225			return nil, errInvalidParameter("request body cannot be read")
226		}
227		if len(bytes.TrimSpace(raw)) == 0 {
228			return nil, errInvalidParameter("request body must be a JSON object")
229		}
230		var body map[string]any
231		if err := json.Unmarshal(raw, &body); err != nil || body == nil {
232			return nil, errInvalidParameter("request body must be a JSON object")
233		}
234		return body, nil
235	}
236	
237	func stringValue(value any) string {
238		if text, ok := value.(string); ok {
239			return text
240		}
241		return ""
242	}
243	
244	// readHealthyInput accepts a new healthy state for one instance from either a
245	// JSON body field ("healthy": true|false) or the ?healthy=true|false query
246	// parameter. The JSON field wins when both carry it. JSON accepts only
247	// booleans, while the query parameter accepts only the lowercase text "true"
248	// or "false"; every other representation is a parameter error.
249	func readHealthyInput(c *gin.Context) (bool, *apiError) {
250		queryValue, queryPresent := c.GetQuery("healthy")
251	
252		if c.Request.Body != nil {
253			raw, err := io.ReadAll(c.Request.Body)
254			if err != nil {
255				return false, errInvalidParameter("request body cannot be read")
256			}
257			if len(bytes.TrimSpace(raw)) > 0 {
258				var body map[string]any
259				if err := json.Unmarshal(raw, &body); err != nil || body == nil {
260					return false, errInvalidParameter("request body must be a JSON object")
261				}
262				if value, present := body["healthy"]; present {
263					healthy, ok := strictBoolValue(value)
264					if !ok {
265						return false, errInvalidParameter("healthy must be a boolean true or false")
266					}
267					return healthy, nil
268				}
269			}
270		}
271	
272		if !queryPresent {
273			return false, errInvalidParameter("healthy must be a boolean true or false")
274		}
275		switch queryValue {
276		case "true":
277			return true, nil
278		case "false":
279			return false, nil
280		default:
281			return false, errInvalidParameter("healthy must be a boolean true or false")
282		}
283	}
284	
285	// requiredText returns the trimmed text for the first matching key, or an error
286	// when the value is missing or blank.
287	func (b *paramBag) requiredText(keys []string, message string) (string, *apiError) {
288		value, ok := b.get(keys)
289		if !ok {
290			return "", errInvalidParameter(message)
291		}
292		text := strings.TrimSpace(stringValue(value))
293		if text == "" {
294			return "", errInvalidParameter(message)
295		}
296		return text, nil
297	}
298	
299	// positiveNumber accepts weights: only numbers strictly greater than zero.
300	func positiveNumber(value any) (float64, bool) {
301		number, ok := toFloat(value)
302		if !ok || math.IsNaN(number) || math.IsInf(number, 0) || number <= 0 {
303			return 0, false
304		}
305		return number, true
306	}
307	
308	// parsePortValue accepts a non-negative integer port number in the range
309	// [0, 9223372036854775807]. JSON numbers and numeric strings are parsed from
310	// their decimal text with exact integer semantics: values above 2^53 keep
311	// their exact value, fractional forms such as 8080.0 or 8.08e3 collapse to
312	// their integer value, and the int64 bound is enforced without rounding, so
313	// 9223372036854775808 is rejected instead of overflowing the conversion.
314	func parsePortValue(value any) (int64, bool) {
315		switch typed := value.(type) {
316		case json.Number:
317			return parsePortText(typed.String())
318		case string:
319			return parsePortText(strings.TrimSpace(typed))
320		case float64:
321			// A float64 at or beyond 2^63 cannot be a valid port: the largest
322			// exactly representable candidate below it is 2^63-1024, and the
323			// int64 conversion of anything larger would overflow.
324			if math.IsNaN(typed) || math.IsInf(typed, 0) || typed != math.Trunc(typed) ||
325				typed < 0 || typed >= 9223372036854775808.0 {
326				return 0, false
327			}
328			return int64(typed), true
329		case int:
330			return int64(typed), typed >= 0
331		case int64:
332			return typed, typed >= 0
333		default:
334			return 0, false
335		}
336	}
337	
338	// portNumberPattern is the decimal grammar a port may use: an integer or a
339	// fixed/scientific decimal with an optional sign.
340	var portNumberPattern = regexp.MustCompile(`^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$`)
341	
342	// parsePortText parses the exact integer value of a decimal number without
343	// going through float64. The mantissa is kept as a digit string and the
344	// exponent as a small int, so huge exponents are rejected by digit counting
345	// instead of materializing enormous integers.
346	func parsePortText(text string) (int64, bool) {
347		// Fast path: a plain decimal integer, exact for the whole int64 range.
348		if number, err := strconv.ParseInt(text, 10, 64); err == nil {
349			return number, number >= 0
350		}
351		if !portNumberPattern.MatchString(text) {
352			return 0, false
353		}
354		negative := strings.HasPrefix(text, "-")
355		mantissa := strings.TrimLeft(text, "+-")
356		exponent := 0
357		if at := strings.IndexAny(mantissa, "eE"); at >= 0 {
358			expText := mantissa[at+1:]
359			mantissa = mantissa[:at]
360			if digits := strings.TrimLeft(strings.TrimLeft(expText, "+-"), "0"); len(digits) > 6 {
361				// |exponent| >= 10^6: the value is either far beyond the int64
362				// bound or far below one; only an all-zero mantissa is still
363				// exactly zero.
364				if allZeroDigits(mantissa) {
365					return 0, true
366				}
367				return 0, false
368			}
369			exponent, _ = strconv.Atoi(expText)
370		}
371		intPart, fracPart := mantissa, ""
372		if at := strings.IndexByte(mantissa, '.'); at >= 0 {
373			intPart, fracPart = mantissa[:at], mantissa[at+1:]
374		}
375		// value = digits * 10^k
376		digits := intPart + fracPart
377		k := exponent - len(fracPart)
378		digits = strings.TrimLeft(digits, "0")
379		for strings.HasSuffix(digits, "0") {
380			digits = digits[:len(digits)-1]
381			k++
382		}
383		if digits == "" {
384			return 0, true // exact zero, in any form
385		}
386		if negative || k < 0 {
387			// A negative port is out of range; a negative remaining exponent
388			// leaves a fractional part, so the value is not an integer.
389			return 0, false
390		}
391		if len(digits)+k > 19 {
392			return 0, false
393		}
394		number, err := strconv.ParseInt(digits+strings.Repeat("0", k), 10, 64)
395		if err != nil {
396			return 0, false // 19 digits but beyond math.MaxInt64
397		}
398		return number, true
399	}
400	
401	// allZeroDigits reports whether a mantissa (digits with an optional dot)
402	// denotes zero.
403	func allZeroDigits(mantissa string) bool {
404		for _, r := range mantissa {
405			if r != '0' && r != '.' {
406				return false
407			}
408		}
409		return true
410	}
411	
412	// strictBoolValue accepts only JSON boolean true or false. Every other
413	// representation (text, numbers) is rejected so all implementations agree.
414	func strictBoolValue(value any) (bool, bool) {
415		typed, ok := value.(bool)
416		return typed, ok
417	}
418	
419	func toFloat(value any) (float64, bool) {
420		switch typed := value.(type) {
421		case float64:
422			return typed, true
423		case int:
424			return float64(typed), true
425		case int64:
426			return float64(typed), true
427		case json.Number:
428			number, err := typed.Float64()
429			if err != nil {
430				return 0, false
431			}
432			return number, true
433		case string:
434			number, err := strconv.ParseFloat(strings.TrimSpace(typed), 64)
435			if err != nil {
436				return 0, false
437			}
438			return number, true
439		default:
440			return 0, false
441		}
442	}
443	
444	func parseHealthValue(value any) (bool, bool) {
445		switch typed := value.(type) {
446		case bool:
447			return typed, true
448		case float64:
449			switch typed {
450			case 1:
451				return true, true
452			case 0:
453				return false, true
454			}
455		case json.Number:
456			if number, err := typed.Float64(); err == nil {
457				switch number {
458				case 1:
459					return true, true
460				case 0:
461					return false, true
462				}
463			}
464		case string:
465			switch strings.ToLower(strings.TrimSpace(typed)) {
466			case "healthy", "up", "on", "true", "1", "yes":
467				return true, true
468			case "unhealthy", "down", "off", "false", "0", "no":
469				return false, true
470			}
471		}
472		return false, false
473	}
474	
475	// Accepted timestamps cover [0000-01-01T00:00:00Z, 10000-01-01T00:00:00Z)
476	// once converted to UTC: the lower bound is included, the upper bound is
477	// excluded. These are exactly the instants the RFC3339 storage format can
478	// write and read back, so anything outside could never round-trip.
479	var (
480		minAcceptedTime = time.Date(0, 1, 1, 0, 0, 0, 0, time.UTC)
481		maxAcceptedTime = time.Date(10000, 1, 1, 0, 0, 0, 0, time.UTC)
482	)
483	
484	func inAcceptedTimeRange(t time.Time) bool {
485		t = t.UTC()
486		return !t.Before(minAcceptedTime) && t.Before(maxAcceptedTime)
487	}
488	
489	func parseTimeValue(value any) (time.Time, bool) {
490		switch typed := value.(type) {
491		case string:
492			text := strings.TrimSpace(typed)
493			if text == "" {
494				return time.Time{}, false
495			}
496			if number, err := strconv.ParseFloat(text, 64); err == nil {
497				return unixTimeInRange(number)
498			}
499			for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05", "2006-01-02 15:04:05"} {
500				if parsed, err := time.Parse(layout, text); err == nil {
501					if !inAcceptedTimeRange(parsed) {
502						return time.Time{}, false
503					}
504					return parsed, true
505				}
506			}
507		case float64:
508			return unixTimeInRange(typed)
509		case json.Number:
510			number, err := typed.Float64()
511			if err != nil {
512				return time.Time{}, false
513			}
514			return unixTimeInRange(number)
515		}
516		return time.Time{}, false
517	}
518	
519	// unixTimeInRange converts a Unix second count that lands inside the
520	// accepted range. The range check runs on the float itself, before any int64
521	// conversion, so non-finite values (NaN, Inf, Infinity with any sign) and
522	// out-of-range finite values are rejected instead of overflowing and
523	// wrapping back into a valid-looking date.
524	func unixTimeInRange(seconds float64) (time.Time, bool) {
525		if math.IsNaN(seconds) || math.IsInf(seconds, 0) ||
526			seconds < float64(minAcceptedTime.Unix()) || seconds >= float64(maxAcceptedTime.Unix()) {
527			return time.Time{}, false
528		}
529		return unixTime(seconds), true
530	}
531	
532	func unixTime(seconds float64) time.Time {
533		whole := int64(seconds)
534		fraction := seconds - float64(whole)
535		return time.Unix(whole, int64(fraction*1e9)).UTC()
536	}
537	
538	// parseTimeout accepts a number of seconds or a duration string such as "30s".
539	// A non-positive duration is reported as invalid by the caller.
540	func parseTimeout(value any) (time.Duration, bool) {
541		switch typed := value.(type) {
542		case float64:
543			if math.IsNaN(typed) || math.IsInf(typed, 0) {
544				return 0, false
545			}
546			return time.Duration(typed * float64(time.Second)), true
547		case json.Number:
548			number, err := typed.Float64()
549			if err != nil || math.IsNaN(number) || math.IsInf(number, 0) {
550				return 0, false
551			}
552			return time.Duration(number * float64(time.Second)), true
553		case string:
554			text := strings.TrimSpace(typed)
555			if text == "" {
556				return 0, false
557			}
558			if duration, err := time.ParseDuration(text); err == nil {
559				return duration, true
560			}
561			if number, err := strconv.ParseFloat(text, 64); err == nil && !math.IsNaN(number) && !math.IsInf(number, 0) {
562				return time.Duration(number * float64(time.Second)), true
563			}
564		}
565		return 0, false
566	}
