745	// handleListServices serves the read-only service overview. It aggregates the
746	// current SQLite records of every service at the requested evaluation point
747	// without creating, updating or deleting anything, and in particular without
748	// running the discovery lost-record cleanup. Lost instances stay stored and
749	// are only counted as lost.
750	func (s *Server) handleListServices(c *gin.Context) {
751		bag, apiErr := buildParamBag(c)
752		if apiErr != nil {
753			writeError(c, apiErr)
754			return
755		}
756		evaluateValue, ok := bag.get(evaluateAtKeys)
757		if !ok {
758			writeError(c, errInvalidParameter("evaluate_at is required"))
759			return
760		}
761		evaluateAt, ok := parseTimeValue(evaluateValue)
762		if !ok {
763			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
764			return
765		}
766		timeoutValue, ok := bag.get(timeoutKeys)
767		if !ok {
768			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
769			return
770		}
771		timeout, ok := parseTimeout(timeoutValue)
772		if !ok || timeout <= 0 {
773			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
774			return
775		}
776	
777		instances, err := s.store.ListAllInstances()
778		if err != nil {
779			writeError(c, errStorageUnavailable())
780			return
781		}
782		for _, instance := range instances {
783			if evaluateAt.Before(instance.HeartbeatAt) {
784				writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
785				return
786			}
787		}
788	
789		// Aggregate records per service. The same counters classify every
790		// record exactly once, so total_instances is always the sum of the
791		// three state counters.
792		byService := make(map[string]*serviceCounters)
793		for _, instance := range instances {
794			counters := byService[instance.ServiceName]
795			if counters == nil {
796				counters = &serviceCounters{}
797				byService[instance.ServiceName] = counters
798			}
799			counters.total++
800			switch {
801			case evaluateAt.After(instance.HeartbeatAt.Add(timeout)):
802				counters.lost++
803			case instance.Healthy:
804				counters.available++
805			default:
806				counters.unhealthyFresh++
807			}
808		}
809	
810		serviceNames := make([]string, 0, len(byService))
811		for serviceName := range byService {
812			serviceNames = append(serviceNames, serviceName)
813		}
814		sort.Strings(serviceNames)
815	
816		services := make([]gin.H, 0, len(serviceNames))
817		for _, serviceName := range serviceNames {
818			counters := byService[serviceName]
819			services = append(services, gin.H{
820				"service_name":              serviceName,
821				"total_instances":           counters.total,
822				"available_instances":       counters.available,
823				"unhealthy_fresh_instances": counters.unhealthyFresh,
824				"lost_instances":            counters.lost,
825			})
826		}
827		c.JSON(200, gin.H{"services": services})
828	}
829	
830	type serviceCounters struct {
831		total          int
832		available      int
833		unhealthyFresh int
834		lost           int
835	}
836	
837	// handleDiscover implements the weighted discovery entry: only explicitly
838	// healthy instances whose last heartbeat is not strictly past the lost
839	// boundary are returned. An instance exactly on the boundary is still
840	// online. Records strictly past the boundary are removed by the lost
841	// cleanup in a single transaction, so a storage failure leaves every
842	// record unchanged and yields no candidate list; online and
843	// unhealthy-but-fresh records are never touched.
844	func (s *Server) handleDiscover(c *gin.Context) {
845		bag, apiErr := buildParamBag(c)
846		if apiErr != nil {
847			writeError(c, apiErr)
848			return
849		}
850		serviceName, apiErr := bag.locateText("serviceName", serviceNameKeys, "service_name must not be empty")
851		if apiErr != nil {
852			writeError(c, apiErr)
853			return
854		}
855		evaluateValue, ok := bag.get(evaluateAtKeys)
856		if !ok {
857			writeError(c, errInvalidParameter("evaluate_at is required"))
858			return
859		}
860		evaluateAt, ok := parseTimeValue(evaluateValue)
861		if !ok {
862			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
863			return
864		}
865		timeoutValue, ok := bag.get(timeoutKeys)
866		if !ok {
867			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
868			return
869		}
870		timeout, ok := parseTimeout(timeoutValue)
871		if !ok || timeout <= 0 {
872			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
873			return
874		}
875	
876		instances, err := s.store.ListInstances(serviceName)
877		if err != nil {
878			writeError(c, errStorageUnavailable())
879			return
880		}
881		for _, instance := range instances {
882			if evaluateAt.Before(instance.HeartbeatAt) {
883				writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
884				return
885			}
886		}
887		candidates := make([]gin.H, 0, len(instances))
888		lostKeys := make([]store.InstanceKey, 0)
889		for _, instance := range instances {
890			if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
891				lostKeys = append(lostKeys, store.InstanceKey{
892					ServiceName: instance.ServiceName,
893					InstanceID:  instance.InstanceID,
894				})
895				continue
896			}
897			if !instance.Healthy {
898				continue
899			}
900			candidates = append(candidates, instanceJSON(instance))
901		}
902		// Lost cleanup deletes records strictly past the timeout. It runs only
903		// after the request is fully validated, and all lost records are removed
904		// in one transaction: a storage failure rolls everything back, so a
905		// failed request never leaves partial deletions behind.
906		if len(lostKeys) > 0 {
907			if err := s.store.DeleteInstances(lostKeys); err != nil {
908				writeError(c, errStorageUnavailable())
909				return
910			}
911		}
912		sortDiscoverHits(candidates)
913		c.JSON(200, gin.H{
914			"service_name":      serviceName,
915			"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
916			"heartbeat_timeout": jsonWeight(timeout.Seconds()),
917			"instances":         candidates,
918		})
919	}
920	
921	// handleBatchDiscover implements POST /api/v1/discover/batch. Several
922	// services share one evaluation point and timeout. Parameters and stored
923	// data are fully validated before any record is removed: every specified
924	// service is read first, the clock-skew guard covers every instance of
925	// every specified service, and lost records across all services are removed
926	// in one transaction so a failure never leaves partial deletions. Services
927	// that are not requested are never read or touched; a requested service
928	// without records yields an empty instance list while keeping its place in
929	// the request order.
930	func (s *Server) handleBatchDiscover(c *gin.Context) {
931		body, apiErr := readJSONObject(c)
932		if apiErr != nil {
933			writeError(c, apiErr)
934			return
935		}
936	
937		rawNames, present := body["service_names"]
938		if !present {
939			writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
940			return
941		}
942		entries, ok := rawNames.([]any)
943		if !ok || len(entries) == 0 {
944			writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
945			return
946		}
947		serviceNames := make([]string, 0, len(entries))
948		seen := make(map[string]struct{}, len(entries))
949		for _, rawName := range entries {
950			name, ok := rawName.(string)
951			if !ok {
952				writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
953				return
954			}
955			name = strings.TrimSpace(name)
956			if name == "" {
957				writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
958				return
959			}
960			if _, duplicated := seen[name]; duplicated {
961				writeError(c, errInvalidParameter("service_names must not contain duplicates"))
962				return
963			}
964			seen[name] = struct{}{}
965			serviceNames = append(serviceNames, name)
966		}
967	
968		evaluateValue, present := body["evaluate_at"]
969		if !present {
970			writeError(c, errInvalidParameter("evaluate_at is required"))
971			return
972		}
973		evaluateAt, ok := parseTimeValue(evaluateValue)
974		if !ok {
975			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
976			return
977		}
978		timeoutValue, present := body["heartbeat_timeout"]
979		if !present {
980			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
981			return
982		}
983		timeout, ok := parseTimeout(timeoutValue)
984		if !ok || timeout <= 0 {
985			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
986			return
987		}
988	
989		// Read every requested service before any classification or deletion,
990		// so a storage read failure changes nothing.
991		byService := make(map[string][]store.Instance, len(serviceNames))
992		for _, serviceName := range serviceNames {
993			instances, err := s.store.ListInstances(serviceName)
994			if err != nil {
995				writeError(c, errStorageUnavailable())
996				return
997			}
998			byService[serviceName] = instances
999		}
1000		// The clock-skew guard covers all records before the lost boundary is
1001		// applied, rejecting the whole batch without deleting anything.
1002		for _, serviceName := range serviceNames {
1003			for _, instance := range byService[serviceName] {
1004				if evaluateAt.Before(instance.HeartbeatAt) {
1005					writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
1006					return
1007				}
1008			}
1009		}
1010	
1011		lostKeys := make([]store.InstanceKey, 0)
1012		for _, serviceName := range serviceNames {
1013			for _, instance := range byService[serviceName] {
1014				if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
1015					lostKeys = append(lostKeys, store.InstanceKey{
1016						ServiceName: instance.ServiceName,
1017						InstanceID:  instance.InstanceID,
1018					})
1019				}
1020			}
1021		}
1022		// All lost records are removed atomically across services.
1023		if len(lostKeys) > 0 {
1024			if err := s.store.DeleteInstances(lostKeys); err != nil {
1025				writeError(c, errStorageUnavailable())
1026				return
1027			}
1028		}
1029	
1030		services := make([]gin.H, 0, len(serviceNames))
1031		for _, serviceName := range serviceNames {
1032			candidates := make([]gin.H, 0)
1033			for _, instance := range byService[serviceName] {
1034				if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
1035					continue
1036				}
1037				if !instance.Healthy {
1038					continue
1039				}
1040				candidates = append(candidates, instanceJSON(instance))
1041			}
1042			sortDiscoverHits(candidates)
1043			services = append(services, gin.H{
1044				"service_name": serviceName,
1045				"instances":    candidates,
1046			})
1047		}
1048		c.JSON(200, gin.H{
1049			"services":          services,
1050			"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
1051			"heartbeat_timeout": jsonWeight(timeout.Seconds()),
1052		})
1053	}
1054	
1055	// handleCleanup implements the standalone lost-instance cleanup entry. An
1056	// omitted service_name evaluates every service; an explicit service_name
1057	// must be non-empty and scopes the cleanup to that one service, leaving
1058	// every other service untouched. Only records strictly past the lost
1059	// boundary are deleted: records exactly on the boundary, still-online
1060	// records and unhealthy-but-fresh records are all kept. Every parameter is
1061	// validated before any deletion, and the deletion itself runs in one
1062	// transaction so a storage failure leaves no partial result.
1063	func (s *Server) handleCleanup(c *gin.Context) {
1064		bag, apiErr := buildParamBag(c)
1065		if apiErr != nil {
1066			writeError(c, apiErr)
1067			return
1068		}
1069	
1070		serviceName := ""
1071		scoped := false
1072		if value, present := bag.get(serviceNameKeys); present {
1073			serviceName = strings.TrimSpace(stringValue(value))
1074			if serviceName == "" {
1075				writeError(c, errInvalidParameter("service_name must not be empty"))
1076				return
1077			}
1078			scoped = true
1079		}
1080		evaluateValue, ok := bag.get(evaluateAtKeys)
1081		if !ok {
1082			writeError(c, errInvalidParameter("evaluate_at is required"))
1083			return
1084		}
1085		evaluateAt, ok := parseTimeValue(evaluateValue)
1086		if !ok {
1087			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
1088			return
1089		}
1090		timeoutValue, ok := bag.get(timeoutKeys)
1091		if !ok {
1092			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
1093			return
1094		}
1095		timeout, ok := parseTimeout(timeoutValue)
1096		if !ok || timeout <= 0 {
1097			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
1098			return
1099		}
1100	
1101		var instances []store.Instance
1102		var err error
1103		if scoped {
1104			instances, err = s.store.ListInstances(serviceName)
1105		} else {
1106			instances, err = s.store.ListAllInstances()
1107		}
1108		if err != nil {
1109			writeError(c, errStorageUnavailable())
1110			return
1111		}
1112		for _, instance := range instances {
1113			if evaluateAt.Before(instance.HeartbeatAt) {
1114				writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
1115				return
1116			}
1117		}
1118	
1119		lost := make([]store.Instance, 0)
1120		keys := make([]store.InstanceKey, 0)
1121		for _, instance := range instances {
1122			if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
1123				lost = append(lost, instance)
1124				keys = append(keys, store.InstanceKey{
1125					ServiceName: instance.ServiceName,
1126					InstanceID:  instance.InstanceID,
1127				})
1128			}
1129		}
1130		if len(keys) > 0 {
1131			if err := s.store.DeleteInstances(keys); err != nil {
1132				writeError(c, errStorageUnavailable())
1133				return
1134			}
1135		}
1136	
1137		sort.SliceStable(lost, func(i, j int) bool {
1138			if lost[i].ServiceName != lost[j].ServiceName {
1139				return lost[i].ServiceName < lost[j].ServiceName
1140			}
1141			return lost[i].InstanceID < lost[j].InstanceID
1142		})
1143		removed := make([]gin.H, 0, len(lost))
1144		for _, instance := range lost {
1145			removed = append(removed, instanceJSON(instance))
1146		}
1147		c.JSON(200, gin.H{
1148			"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
1149			"heartbeat_timeout": jsonWeight(timeout.Seconds()),
1150			"removed":           len(removed),
1151			"instances":         removed,
1152		})
1153	}
1154	
1155	// sortDiscoverHits orders discovery hits by weight descending, then instance
1156	// id ascending, giving deterministic output for identical input.
1157	func sortDiscoverHits(instances []gin.H) {
1158		sort.SliceStable(instances, func(i, j int) bool {
1159			leftWeight, _ := toFloat(instances[i]["weight"])
1160			rightWeight, _ := toFloat(instances[j]["weight"])
1161			if leftWeight != rightWeight {
1162				return leftWeight > rightWeight
1163			}
1164			return stringValue(instances[i]["instance_id"]) < stringValue(instances[j]["instance_id"])
1165		})
1166	}
1167	
1168	// sortInstances orders by weight descending, heartbeat newest first, then
1169	// instance id ascending, giving deterministic output for identical input.
1170	func sortInstances(instances []gin.H) {
1171		sort.SliceStable(instances, func(i, j int) bool {
1172			left, right := instances[i], instances[j]
1173			leftWeight, _ := toFloat(left["weight"])
1174			rightWeight, _ := toFloat(right["weight"])
1175			if leftWeight != rightWeight {
1176				return leftWeight > rightWeight
1177			}
1178			leftHeartbeat, _ := parseTimeValue(left["heartbeat_at"])
1179			rightHeartbeat, _ := parseTimeValue(right["heartbeat_at"])
1180			if !leftHeartbeat.Equal(rightHeartbeat) {
1181				return leftHeartbeat.After(rightHeartbeat)
1182			}
1183			return stringValue(left["instance_id"]) < stringValue(right["instance_id"])
1184		})
1185	}
