// handleListInstances returns all records of a service, never removing any.
func (s *Server) handleListInstances(c *gin.Context) {
	bag, apiErr := buildParamBag(c)
	if apiErr != nil {
		writeError(c, apiErr)
		return
	}
	serviceName, apiErr := bag.locateText("serviceName", serviceNameKeys, "service_name must not be empty")
	if apiErr != nil {
		writeError(c, apiErr)
		return
	}
	instances, err := s.store.ListInstances(serviceName)
	if err != nil {
		writeError(c, errStorageUnavailable())
		return
	}
	wantHealthy, hasFilter := false, false
	if healthFilter, present := bag.get(healthKeys); present {
		parsed, ok := parseHealthValue(healthFilter)
		if !ok {
			writeError(c, errInvalidParameter("healthy must be a boolean health state"))
			return
		}
		wantHealthy, hasFilter = parsed, true
	}
	results := make([]gin.H, 0, len(instances))
	for _, instance := range instances {
		if hasFilter && instance.Healthy != wantHealthy {
			continue
		}
		results = append(results, instanceJSON(instance))
	}
	sortInstances(results)
	c.JSON(200, gin.H{"service_name": serviceName, "instances": results})
}

// handleListServices serves the read-only service overview. It aggregates the
// current SQLite records of every service at the requested evaluation point
// without creating, updating or deleting anything, and in particular without
// running the discovery lost-record cleanup. Lost instances stay stored and
// are only counted as lost.
func (s *Server) handleListServices(c *gin.Context) {
	bag, apiErr := buildParamBag(c)
	if apiErr != nil {
		writeError(c, apiErr)
		return
	}
	evaluateValue, ok := bag.get(evaluateAtKeys)
	if !ok {
		writeError(c, errInvalidParameter("evaluate_at is required"))
		return
	}
	evaluateAt, ok := parseTimeValue(evaluateValue)
	if !ok {
		writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
		return
	}
	timeoutValue, ok := bag.get(timeoutKeys)
	if !ok {
		writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
		return
	}
	timeout, ok := parseTimeout(timeoutValue)
	if !ok || timeout <= 0 {
		writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
		return
	}

	instances, err := s.store.ListAllInstances()
	if err != nil {
		writeError(c, errStorageUnavailable())
		return
	}
	for _, instance := range instances {
		if evaluateAt.Before(instance.HeartbeatAt) {
			writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
			return
		}
	}

	// Aggregate records per service. The same counters classify every
	// record exactly once, so total_instances is always the sum of the
	// three state counters.
	byService := make(map[string]*serviceCounters)
	for _, instance := range instances {
		counters := byService[instance.ServiceName]
		if counters == nil {
			counters = &serviceCounters{}
			byService[instance.ServiceName] = counters
		}
		counters.total++
		switch {
		case evaluateAt.After(instance.HeartbeatAt.Add(timeout)):
			counters.lost++
		case instance.Healthy:
			counters.available++
		default:
			counters.unhealthyFresh++
		}
	}

	serviceNames := make([]string, 0, len(byService))
	for serviceName := range byService {
		serviceNames = append(serviceNames, serviceName)
	}
	sort.Strings(serviceNames)

	services := make([]gin.H, 0, len(serviceNames))
	for _, serviceName := range serviceNames {
		counters := byService[serviceName]
		services = append(services, gin.H{
			"service_name":              serviceName,
			"total_instances":           counters.total,
			"available_instances":       counters.available,
			"unhealthy_fresh_instances": counters.unhealthyFresh,
			"lost_instances":            counters.lost,
		})
	}
	c.JSON(200, gin.H{"services": services})
}

type serviceCounters struct {
	total          int
	available      int
	unhealthyFresh int
	lost           int
}

// handleDiscover implements the weighted discovery entry: only explicitly
// healthy instances whose last heartbeat is not strictly past the lost
// boundary are returned. An instance exactly on the boundary is still
// online. Records strictly past the boundary are removed by the lost
// cleanup in a single transaction, so a storage failure leaves every
// record unchanged and yields no candidate list; online and
// unhealthy-but-fresh records are never touched.
func (s *Server) handleDiscover(c *gin.Context) {
	bag, apiErr := buildParamBag(c)
	if apiErr != nil {
		writeError(c, apiErr)
		return
	}
	serviceName, apiErr := bag.locateText("serviceName", serviceNameKeys, "service_name must not be empty")
	if apiErr != nil {
		writeError(c, apiErr)
		return
	}
	evaluateValue, ok := bag.get(evaluateAtKeys)
	if !ok {
		writeError(c, errInvalidParameter("evaluate_at is required"))
		return
	}
	evaluateAt, ok := parseTimeValue(evaluateValue)
	if !ok {
		writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
		return
	}
	timeoutValue, ok := bag.get(timeoutKeys)
	if !ok {
		writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
		return
	}
	timeout, ok := parseTimeout(timeoutValue)
	if !ok || timeout <= 0 {
		writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
		return
	}

	instances, err := s.store.ListInstances(serviceName)
	if err != nil {
		writeError(c, errStorageUnavailable())
		return
	}
	for _, instance := range instances {
		if evaluateAt.Before(instance.HeartbeatAt) {
			writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
			return
		}
	}
	candidates := make([]gin.H, 0, len(instances))
	lostKeys := make([]store.InstanceKey, 0)
	for _, instance := range instances {
		if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
			lostKeys = append(lostKeys, store.InstanceKey{
				ServiceName: instance.ServiceName,
				InstanceID:  instance.InstanceID,
			})
			continue
		}
		if !instance.Healthy {
			continue
		}
		candidates = append(candidates, instanceJSON(instance))
	}
	// Lost cleanup deletes records strictly past the timeout. It runs only
	// after the request is fully validated, and all lost records are removed
	// in one transaction: a storage failure rolls everything back, so a
	// failed request never leaves partial deletions behind.
	if len(lostKeys) > 0 {
		if err := s.store.DeleteInstances(lostKeys); err != nil {
			writeError(c, errStorageUnavailable())
			return
		}
	}
	sortDiscoverHits(candidates)
	c.JSON(200, gin.H{
		"service_name":      serviceName,
		"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
		"heartbeat_timeout": jsonWeight(timeout.Seconds()),
		"instances":         candidates,
	})
}

// handleBatchDiscover implements POST /api/v1/discover/batch. Several
// services share one evaluation point and timeout. Parameters and stored
// data are fully validated before any record is removed: every specified
// service is read first, the clock-skew guard covers every instance of
// every specified service, and lost records across all services are removed
// in one transaction so a failure never leaves partial deletions. Services
// that are not requested are never read or touched; a requested service
// without records yields an empty instance list while keeping its place in
// the request order.
func (s *Server) handleBatchDiscover(c *gin.Context) {
	body, apiErr := readJSONObject(c)
	if apiErr != nil {
		writeError(c, apiErr)
		return
	}

	rawNames, present := body["service_names"]
	if !present {
		writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
		return
	}
	entries, ok := rawNames.([]any)
	if !ok || len(entries) == 0 {
		writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
		return
	}
	serviceNames := make([]string, 0, len(entries))
	seen := make(map[string]struct{}, len(entries))
	for _, rawName := range entries {
		name, ok := rawName.(string)
		if !ok {
			writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
			return
		}
		name = strings.TrimSpace(name)
		if name == "" {
			writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
			return
		}
		if _, duplicated := seen[name]; duplicated {
			writeError(c, errInvalidParameter("service_names must not contain duplicates"))
			return
		}
		seen[name] = struct{}{}
		serviceNames = append(serviceNames, name)
	}

	evaluateValue, present := body["evaluate_at"]
	if !present {
		writeError(c, errInvalidParameter("evaluate_at is required"))
		return
	}
	evaluateAt, ok := parseTimeValue(evaluateValue)
	if !ok {
		writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
		return
	}
	timeoutValue, present := body["heartbeat_timeout"]
	if !present {
		writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
		return
	}
	timeout, ok := parseTimeout(timeoutValue)
	if !ok || timeout <= 0 {
		writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
		return
	}

	// Read every requested service before any classification or deletion,
	// so a storage read failure changes nothing.
	byService := make(map[string][]store.Instance, len(serviceNames))
	for _, serviceName := range serviceNames {
		instances, err := s.store.ListInstances(serviceName)
		if err != nil {
			writeError(c, errStorageUnavailable())
			return
		}
		byService[serviceName] = instances
	}
	// The clock-skew guard covers all records before the lost boundary is
	// applied, rejecting the whole batch without deleting anything.
	for _, serviceName := range serviceNames {
		for _, instance := range byService[serviceName] {
			if evaluateAt.Before(instance.HeartbeatAt) {
				writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
				return
			}
		}
	}

	lostKeys := make([]store.InstanceKey, 0)
	for _, serviceName := range serviceNames {
		for _, instance := range byService[serviceName] {
			if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
				lostKeys = append(lostKeys, store.InstanceKey{
					ServiceName: instance.ServiceName,
					InstanceID:  instance.InstanceID,
				})
			}
		}
	}
	// All lost records are removed atomically across services.
	if len(lostKeys) > 0 {
		if err := s.store.DeleteInstances(lostKeys); err != nil {
			writeError(c, errStorageUnavailable())
			return
		}
	}

	services := make([]gin.H, 0, len(serviceNames))
	for _, serviceName := range serviceNames {
		candidates := make([]gin.H, 0)
		for _, instance := range byService[serviceName] {
			if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
				continue
			}
			if !instance.Healthy {
				continue
			}
			candidates = append(candidates, instanceJSON(instance))
		}
		sortDiscoverHits(candidates)
		services = append(services, gin.H{
			"service_name": serviceName,
			"instances":    candidates,
		})
	}
	c.JSON(200, gin.H{
		"services":          services,
		"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
		"heartbeat_timeout": jsonWeight(timeout.Seconds()),
	})
}

// handleCleanup implements the standalone lost-instance cleanup entry. An
// omitted service_name evaluates every service; an explicit service_name
// must be non-empty and scopes the cleanup to that one service, leaving
// every other service untouched. Only records strictly past the lost
// boundary are deleted: records exactly on the boundary, still-online
// records and unhealthy-but-fresh records are all kept. Every parameter is
// validated before any deletion, and the deletion itself runs in one
// transaction so a storage failure leaves no partial result.
func (s *Server) handleCleanup(c *gin.Context) {
	bag, apiErr := buildParamBag(c)
	if apiErr != nil {
		writeError(c, apiErr)
		return
	}

	serviceName := ""
	scoped := false
	if value, present := bag.get(serviceNameKeys); present {
		serviceName = strings.TrimSpace(stringValue(value))
		if serviceName == "" {
			writeError(c, errInvalidParameter("service_name must not be empty"))
			return
		}
		scoped = true
	}
	evaluateValue, ok := bag.get(evaluateAtKeys)
	if !ok {
		writeError(c, errInvalidParameter("evaluate_at is required"))
		return
	}
	evaluateAt, ok := parseTimeValue(evaluateValue)
	if !ok {
		writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
		return
	}
	timeoutValue, ok := bag.get(timeoutKeys)
	if !ok {
		writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
		return
	}
	timeout, ok := parseTimeout(timeoutValue)
	if !ok || timeout <= 0 {
		writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
		return
	}

	var instances []store.Instance
	var err error
	if scoped {
		instances, err = s.store.ListInstances(serviceName)
	} else {
		instances, err = s.store.ListAllInstances()
	}
	if err != nil {
		writeError(c, errStorageUnavailable())
		return
	}
	for _, instance := range instances {
		if evaluateAt.Before(instance.HeartbeatAt) {
			writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
			return
		}
	}

	lost := make([]store.Instance, 0)
	keys := make([]store.InstanceKey, 0)
	for _, instance := range instances {
		if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
			lost = append(lost, instance)
			keys = append(keys, store.InstanceKey{
				ServiceName: instance.ServiceName,
				InstanceID:  instance.InstanceID,
			})
		}
	}
	if len(keys) > 0 {
		if err := s.store.DeleteInstances(keys); err != nil {
			writeError(c, errStorageUnavailable())
			return
		}
	}

	sort.SliceStable(lost, func(i, j int) bool {
		if lost[i].ServiceName != lost[j].ServiceName {
			return lost[i].ServiceName < lost[j].ServiceName
		}
		return lost[i].InstanceID < lost[j].InstanceID
	})
	removed := make([]gin.H, 0, len(lost))
	for _, instance := range lost {
		removed = append(removed, instanceJSON(instance))
	}
	c.JSON(200, gin.H{
		"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
		"heartbeat_timeout": jsonWeight(timeout.Seconds()),
		"removed":           len(removed),
		"instances":         removed,
	})
}

// sortDiscoverHits orders discovery hits by weight descending, then instance
// id ascending, giving deterministic output for identical input.
func sortDiscoverHits(instances []gin.H) {
	sort.SliceStable(instances, func(i, j int) bool {
		leftWeight, _ := toFloat(instances[i]["weight"])
		rightWeight, _ := toFloat(instances[j]["weight"])
		if leftWeight != rightWeight {
			return leftWeight > rightWeight
		}
		return stringValue(instances[i]["instance_id"]) < stringValue(instances[j]["instance_id"])
	})
}

// sortInstances orders by weight descending, heartbeat newest first, then
// instance id ascending, giving deterministic output for identical input.
func sortInstances(instances []gin.H) {
	sort.SliceStable(instances, func(i, j int) bool {
		left, right := instances[i], instances[j]
		leftWeight, _ := toFloat(left["weight"])
		rightWeight, _ := toFloat(right["weight"])
		if leftWeight != rightWeight {
			return leftWeight > rightWeight
		}
		leftHeartbeat, _ := parseTimeValue(left["heartbeat_at"])
		rightHeartbeat, _ := parseTimeValue(right["heartbeat_at"])
		if !leftHeartbeat.Equal(rightHeartbeat) {
			return leftHeartbeat.After(rightHeartbeat)
		}
		return stringValue(left["instance_id"]) < stringValue(right["instance_id"])
	})
}

package api

import (
	"net/http"
	"regexp"
	"strings"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/service-discovery-api/internal/store"
)

var emptyServicePaths = []*regexp.Regexp{
	regexp.MustCompile(`^/api/v1/services/(/instances)?/?$`),
	regexp.MustCompile(`^/api/v1/services/(/instances/batch)/?$`),
	regexp.MustCompile(`^/api/v1/services/(/discover)/?$`),
	regexp.MustCompile(`^/api/v1/services/(/instances/[^/]+/heartbeat)/?$`),
	regexp.MustCompile(`^/api/v1/services/(/instances/weight)/?$`),
	regexp.MustCompile(`^/api/v1/services/(/instances/[^/]+/weight)/?$`),
	regexp.MustCompile(`^/api/v1/services/(/instances/health)/?$`),
	regexp.MustCompile(`^/api/v1/services/(/instances/[^/]+/health)/?$`),
	regexp.MustCompile(`^/api/v1/services/[^/]+/instances/(/health)/?$`),
	regexp.MustCompile(`^/api/v1/services/[^/]+/instances/(/weight)/?$`),
}

// Server wires the store to every public HTTP entry point.
type Server struct {
	store *store.Store
}

// NewRouter wires the public HTTP surface. The service contract in README.md
// describes the single-error-object shape every entry must keep.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	server := &Server{store: st}

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	// Registration and update share one upsert entry; repeated registration
	// of the same (service, instance) pair overwrites the current record.
	router.POST("/api/v1/services/:serviceName/instances", server.handleUpsert)
	router.PUT("/api/v1/services/:serviceName/instances/:instanceId", server.handleUpsert)
	router.POST("/api/v1/register", server.handleUpsert)
	router.POST("/api/v1/instances", server.handleUpsert)
	router.PUT("/api/v1/instances", server.handleUpsert)

	// Batch registration applies several upserts of one service in one
	// atomic request. The path entry takes its service name from the path;
	// the register entry takes it from the body's service_name field.
	router.POST("/api/v1/services/:serviceName/instances/batch", server.handleBatchUpsertByPath)
	router.POST("/api/v1/register/batch", server.handleBatchUpsertByBody)

	// Public instance query entries.
	// Read-only overview of every service that still has instance records.
	router.GET("/api/v1/services", server.handleListServices)
	router.GET("/api/v1/services/:serviceName/instances", server.handleListInstances)
	router.GET("/api/v1/services/:serviceName/instances/:instanceId", server.handleGetInstance)
	router.GET("/api/v1/services/:serviceName/instances/:instanceId/health", server.handleGetHealth)
	router.GET("/api/v1/services/:serviceName/instances/:instanceId/weight", server.handleGetWeight)
	router.GET("/api/v1/services/:serviceName/instances/:instanceId/heartbeat", server.handleGetHeartbeat)
	router.GET("/api/v1/instances", server.handleGetInstance)
	router.GET("/api/v1/instances/health", server.handleGetHealth)
	router.GET("/api/v1/instances/weight", server.handleGetWeight)
	router.GET("/api/v1/instances/heartbeat", server.handleGetHeartbeat)
	router.GET("/api/v1/list", server.handleListInstances)

	// Instance deletion.
	router.DELETE("/api/v1/services/:serviceName/instances/:instanceId", server.handleDelete)
	router.POST("/api/v1/services/:serviceName/instances/:instanceId/delete", server.handleDelete)
	router.DELETE("/api/v1/instances", server.handleDelete)
	router.POST("/api/v1/deregister", server.handleDelete)

	// Heartbeat renewal: only heartbeat_at is replaced; the caller never
	// resubmits address, port, health state or weight.
	router.POST("/api/v1/services/:serviceName/instances/:instanceId/heartbeat", server.handleHeartbeat)
	router.POST("/api/v1/heartbeat", server.handleBatchHeartbeat)

	// Weight-only updates replace just weight; address, port, health state
	// and heartbeat time keep their current values, and the upsert
	// overwrite semantics stay unchanged.
	router.PUT("/api/v1/services/:serviceName/instances/weight", server.handleBatchUpdateWeight)
	router.PUT("/api/v1/services/:serviceName/instances/:instanceId/weight", server.handleUpdateWeight)

	// Health-state-only updates replace just the healthy flag; address,
	// port, weight and heartbeat time keep their current values, no missing
	// instance is created and no heartbeat is renewed.
	router.PUT("/api/v1/services/:serviceName/instances/health", server.handleBatchUpdateHealth)
	router.PUT("/api/v1/services/:serviceName/instances/:instanceId/health", server.handleUpdateHealth)

	// Discovery of healthy instances with heartbeat-lost removal.
	router.GET("/api/v1/services/:serviceName/discover", server.handleDiscover)
	router.GET("/api/v1/discover", server.handleDiscover)
	router.POST("/api/v1/services/:serviceName/discover", server.handleDiscover)
	router.POST("/api/v1/discover", server.handleDiscover)
	router.POST("/api/v1/discover/batch", server.handleBatchDiscover)

	// Standalone lost-instance cleanup across one or all services.
	router.POST("/api/v1/cleanup", server.handleCleanup)

	router.NoRoute(func(c *gin.Context) {
		// An empty final path segment (e.g. /api/v1/services//instances)
		// carries an empty service name and must be a parameter error.
		for _, pattern := range emptyServicePaths {
			if pattern.MatchString(c.Request.URL.Path) {
				switch {
				case strings.HasSuffix(c.Request.URL.Path, "/discover"):
					c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					server.handleDiscover(c)
				case strings.HasSuffix(c.Request.URL.Path, "/heartbeat"):
					c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					server.handleHeartbeat(c)
				case strings.HasSuffix(c.Request.URL.Path, "/instances/batch"):
					c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					server.handleBatchUpsertByPath(c)
				case c.Request.Method == http.MethodPut && strings.HasSuffix(c.Request.URL.Path, "/instances/weight"):
					c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					server.handleBatchUpdateWeight(c)
				case c.Request.Method == http.MethodPut && strings.HasSuffix(c.Request.URL.Path, "/instances/health"):
					c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					server.handleBatchUpdateHealth(c)
				case c.Request.Method == http.MethodPut && strings.HasSuffix(c.Request.URL.Path, "/health"):
					emptyInstance := strings.HasSuffix(c.Request.URL.Path, "//health")
					if emptyInstance {
						c.Params = gin.Params{
							{Key: "serviceName", Value: ""},
							{Key: "instanceId", Value: ""},
						}
					} else {
						c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					}
					server.handleUpdateHealth(c)
				case c.Request.Method == http.MethodPut && strings.HasSuffix(c.Request.URL.Path, "/weight"):
					emptyInstance := strings.HasSuffix(c.Request.URL.Path, "//weight")
					if emptyInstance {
						c.Params = gin.Params{
							{Key: "serviceName", Value: ""},
							{Key: "instanceId", Value: ""},
						}
					} else {
						c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					}
					server.handleUpdateWeight(c)
				case c.Request.Method == http.MethodDelete || (c.Request.Method == http.MethodPost && strings.HasSuffix(c.Request.URL.Path, "/delete")):
					c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					server.handleDelete(c)
				case c.Request.Method == http.MethodPost:
					c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					server.handleUpsert(c)
				default:
					c.Params = gin.Params{{Key: "serviceName", Value: ""}}
					server.handleListInstances(c)
				}
				return
			}
		}
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}

